{
  "items": [
    {
      "name": "Set.encard_pi_eq_prod_encard",
      "module_name": "Mathlib.Data.Set.Card",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [h : Fintype α] {ι : α → Type u_3} {s : (i : α) → Set (ι i)},\n  (Set.univ.pi s).encard = ∏ i, (s i).encard"
    },
    {
      "name": "Cardinal.mk_prod",
      "module_name": "Mathlib.SetTheory.Cardinal.Defs",
      "kind": "theorem",
      "type": "∀ (α : Type u) (β : Type v),\n  Cardinal.mk (α × β) = Cardinal.lift.{v, u} (Cardinal.mk α) * Cardinal.lift.{u, v} (Cardinal.mk β)"
    },
    {
      "name": "Finsupp.card_pi",
      "module_name": "Mathlib.Data.Finset.Finsupp",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : Type u_2} [inst : Zero α] (f : ι →₀ Finset α), f.pi.card = f.prod fun i => ↑(f i).card"
    },
    {
      "name": "Set.encard_prod",
      "module_name": "Mathlib.Data.Set.Card",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} {s : Set α} {t : Set β}, (s ×ˢ t).encard = s.encard * t.encard"
    },
    {
      "name": "Set.ncard_prod",
      "module_name": "Mathlib.Data.Set.Card",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} {s : Set α} {t : Set β}, (s ×ˢ t).ncard = s.ncard * t.ncard"
    },
    {
      "name": "Nat.card_pi",
      "module_name": "Mathlib.SetTheory.Cardinal.Finite",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : α → Type u_3} [inst : Fintype α], Nat.card ((a : α) → β a) = ∏ a, Nat.card (β a)"
    },
    {
      "name": "Cardinal.mk_setProd",
      "module_name": "Mathlib.SetTheory.Cardinal.Basic",
      "kind": "theorem",
      "type": "∀ {α β : Type u} (s : Set α) (t : Set β), Cardinal.mk ↑(s ×ˢ t) = Cardinal.mk ↑s * Cardinal.mk ↑t"
    },
    {
      "name": "Cardinal.mk_pi",
      "module_name": "Mathlib.SetTheory.Cardinal.Defs",
      "kind": "theorem",
      "type": "∀ {ι : Type u} (α : ι → Type v), Cardinal.mk ((i : ι) → α i) = Cardinal.prod fun i => Cardinal.mk (α i)"
    }
  ]
}
